import { Histogram } from '@absoluteui/components/histogram';

const values = Array.from({ length: 500 }, (_, i) => 80 + ((i * 37) % 200));
const host = document.createElement('div');
document.body.append(host);
const chart = Histogram.create(host, {
  label: 'Response times',
  values,
  binFormat: { style: 'unit', unit: 'millisecond' },
  xAxis: { label: 'Response time' },
});
host.dataset.bins = String(chart.bins.length);

import { Histogram, computeBins } from '@absoluteui/components/histogram';

const scores = [12, 45, 67, 68, 71, 88, 90, 95, null, 102];
const thresholds = [0, 50, 70, 90, 100];
const { bins, outside, missing } = computeBins(scores, { bins: thresholds });
const host = document.querySelector<HTMLElement>('#scores');
if (host) {
  Histogram.create(host, { label: 'Exam scores', values: scores, bins: thresholds, color: 3, dataTable: 'visible' });
  host.dataset.counts = bins.map((b) => String(b.count)).join(',');
  host.dataset.outside = String(outside + missing);
}
